/// The anatomical figure itself: the real image (transparent
/// background — it sits directly on Theme.background, true black in
/// dark mode, system background in light mode, with no card or panel
/// behind it), with a tappable tint/glow overlay over each muscle region. `highlighted` is
/// the set of muscles lit up right now (bright + glow — injury marks, or
/// the live workout muscles). `recovery` colours each muscle by its
/// recovery state from logged history (fresh = bright pink, recovering =
/// purple); the highlight wins over the recovery colour. A muscle with
/// no state shows the image's own red — that is the resting state.
/// `onTap` fires with the muscle tapped (nil = display only). The figure
/// scales to fit its frame; the canvas is 200×400, the same aspect as
/// the images, so the overlays land on the muscles in the pictures.
struct BodyFigureView: View {
    /// Light mode: the grey painting is lightened to match the light grey
    /// UI (DaRon, Nov 12); the lit muscles keep their accent color.
    @Environment(\.colorScheme) private var colorScheme
    let side: BodyDiagramSide
    var highlighted: Set<MuscleID> = []
    var recovery: [MuscleID: MuscleRecovery] = [:]
    /// Highlight colour for lit muscles. Nil = the default orange-red
    /// (the injury diagram keeps it: "this hurts" reads as warm). The
    /// live workout figure passes the app's accent.
    var litColor: Color? = nil
    /// The prime movers among `highlighted`. Nil = every lit muscle at
    /// full strength. When set, lit muscles NOT in it are synergists and
    /// draw at reduced strength — a lighter fill, a faint edge, no glow —
    /// so the figure shows what the exercise mainly works.
    var primary: Set<MuscleID>? = nil
    /// Injured areas, lit in the warm injury colour alongside the main
    /// highlight (the live body's "Injuries" and "All" views). A muscle in
    /// both shows the main highlight.
    var injured: Set<MuscleID> = []
    var onTap: ((MuscleID) -> Void)? = nil

    private var anatomyName: String { side == .front ? "BodyAnatomyFront" : "BodyAnatomyBack" }
    /// Brightness map of the painting (white = light): multiplied by the
    /// highlight colour it gives a tinted muscle with its fibres intact.
    private var shadeName: String { side == .front ? "BodyShadeFront" : "BodyShadeBack" }

    /// Never lit for work or recovery (DaRon, Nov 14): the feet only ever
    /// lit because calf and ankle work maps onto them, and a glowing foot
    /// read as the thing being trained. A marked foot injury still shows.
    static let neverLit: Set<MuscleID> = [.footLeft, .footRight]

    private var primaryLit: Set<MuscleID> {
        guard let primary else { return highlighted.subtracting(Self.neverLit) }
        return highlighted.intersection(primary).subtracting(Self.neverLit)
    }
    private var secondaryLit: Set<MuscleID> {
        guard let primary else { return [] }
        return highlighted.subtracting(primary).subtracting(Self.neverLit)
    }

    /// The shade image tinted with the highlight colour, cut to the given
    /// areas' exact outlines.
    @ViewBuilder
    private func tintLayer(ids: Set<MuscleID>, scale: CGFloat, color: Color? = nil) -> some View {
        if !ids.isEmpty {
            let specs = muscleSpecs.filter { $0.side == side && ids.contains($0.id) }
            let tint = color ?? litColor ?? Self.litGlow
            Image(shadeName)
                .resizable()
                .aspectRatio(contentMode: .fit)
                .colorMultiply(tint)
                .mask {
                    Path { path in
                        for spec in specs { path.addPath(overlayPath(spec, scale: scale)) }
                    }
                    .fill(style: FillStyle())
                    .frame(width: 200 * scale, height: 400 * scale)
                }
                // The accent's glow (DaRon): the same soft halo the + button
                // and the side bar's current page have.
                .shadow(color: tint.opacity(0.5), radius: 10)
                .animation(AppAnimation.snappy, value: ids)
        }
    }

    /// Muscles in a recovery state, unless a highlight or injury covers them.
    private func recoveryIDs(_ state: MuscleRecovery) -> Set<MuscleID> {
        Set(recovery.compactMap { $0.value == state ? $0.key : nil })
            .subtracting(highlighted).subtracting(injured).subtracting(Self.neverLit)
    }

    /// Injured areas not already under the main highlight.
    private var injuredOnly: Set<MuscleID> { injured.subtracting(highlighted) }

    /// Segmented style (Nov 12, approved preview): a dark body silhouette,
    /// every muscle its own flat grey shape with the gaps between them
    /// showing, and colour only where it means something. Joints, hands,
    /// feet and head stay silhouette-coloured at rest.
    private static let silhouette = Color(UIColor { tc in
        tc.userInterfaceStyle == .dark
            ? UIColor(red: 38/255, green: 38/255, blue: 44/255, alpha: 1)
            : UIColor(white: 0.84, alpha: 1)
    })
    /// Also the "Resting" swatch in the Body page legend.
    static let muscleRest = Color(UIColor { tc in
        tc.userInterfaceStyle == .dark
            ? UIColor(red: 70/255, green: 70/255, blue: 78/255, alpha: 1)
            : UIColor(white: 0.68, alpha: 1)
    })

    /// State palette, drawn like the lit muscles (the painting tinted, with
    /// the glow) so recovery reads as clearly as the working muscles
    /// (DaRon, Nov 13: the white dashes threw him off). Fresh = bright
    /// pink, recovering = violet: different hue AND brightness, so they
    /// stay apart without colour.
    static let freshColor = Color(red: 1.0, green: 0.22, blue: 0.40)
    static let recoveringColor = Color(red: 0.52, green: 0.36, blue: 1.0)
    private static let litFill = Color(red: 1.0, green: 0.38, blue: 0.08).opacity(0.85)
    private static let litGlow = Color(red: 1.0, green: 0.45, blue: 0.1)
    private static let litStroke = Color.white.opacity(0.9)
    private static let stateStroke = Color.white.opacity(0.35)

    /// Called when a drag turns the body round, so the page's Front/Back
    /// control follows (3D body only).
    var onSideChange: ((BodyDiagramSide) -> Void)? = nil

    /// The 3D body (Nov 14): the real model, dragged round, every muscle
    /// coloured on the model itself. The flat painting is the fallback if
    /// the model can't load (no Metal).
    var body: some View {
        if BodyModel.shared.isReady {
            Body3DView(side: side, palette: palette, onTap: onTap, onSideChange: onSideChange)
                .accessibilityElement(children: .ignore)
                .accessibilityLabel("Body, \(side.label.lowercased()) view")
                .accessibilityValue(accessibilityLitText)
                .accessibilityHint(onTap == nil ? "" : "Use the actions to mark a muscle")
                .accessibilityActions {
                    if let onTap {
                        ForEach(muscleSpecs.filter { $0.side == side }, id: \.id) { spec in
                            Button(spec.id.accessibilityLabel) { onTap(spec.id) }
                        }
                    }
                }
        } else {
            flatFigure
        }
    }

    /// What colours each muscle gets, in drawing order (later wins).
    private var palette: [MuscleID: BodyTint] {
        var p: [MuscleID: BodyTint] = [:]
        for id in recoveryIDs(.fresh) { p[id] = BodyTint(color: Self.freshColor, strength: 1) }
        for id in recoveryIDs(.recovering) { p[id] = BodyTint(color: Self.recoveringColor, strength: 1) }
        for id in injuredOnly { p[id] = BodyTint(color: Self.litGlow, strength: 1) }
        let lit = litColor ?? Self.litGlow
        for id in secondaryLit { p[id] = BodyTint(color: lit, strength: 0.55) }
        for id in primaryLit { p[id] = BodyTint(color: lit, strength: 1) }
        return p
    }

    private var accessibilityLitText: String {
        let names = (primaryLit.union(secondaryLit).union(injuredOnly))
            .map(\.accessibilityLabel).sorted()
        return names.isEmpty ? "" : names.joined(separator: ", ")
    }

    private var flatFigure: some View {
        GeometryReader { proxy in
            let scale = min(proxy.size.width / 200, proxy.size.height / 400)
            let w = 200 * scale, h = 400 * scale
            // The outer ZStack is given the full proxy size so its
            // bounds contain the positioned figure (a positioned child
            // contributes no size to its parent, so without this frame
            // the outer ZStack would be 0x0 — harmless for rendering
            // but it would put the figure outside the parent's bounds
            // for hit-testing). NOTE: this frame alone did NOT fix the
            // taps (build #6 still failed) — the actual defect was the
            // tap-location coordinate space, fixed in the gesture
            // below. Kept because the sizing is still correct.
            ZStack {
                // No card behind the figure: the images are transparent
                // now (white baked into the PNGs was converted to alpha),
                // so the red figure sits directly on the app's own
                // background — true black in dark mode, system background
                // in light mode — with no white box anywhere (DaRon,
                // 21:36: "background of body needs to match").
                ZStack {
                    // Realistic anatomy in grey underneath (Nov 12 hybrid):
                    // head, hands, feet, elbows and the gaps between the
                    // muscle shapes show real anatomical detail.
                    Image(anatomyName)
                        .resizable()
                        .aspectRatio(contentMode: .fit)
                        .brightness(colorScheme == .light ? 0.3 : 0)
                        .contrast(colorScheme == .light ? 0.85 : 1)
                    // Lit muscles: the painting itself, recoloured to the
                    // highlight colour — its own light and dark kept, so
                    // fibres and tendons stay visible (Nov 12). Prime
                    // movers full strength, synergists blended lighter.
                    tintLayer(ids: recoveryIDs(.fresh), scale: scale, color: Self.freshColor)
                    tintLayer(ids: recoveryIDs(.recovering), scale: scale, color: Self.recoveringColor)
                    tintLayer(ids: injuredOnly, scale: scale, color: Self.litGlow)
                    if !highlighted.isEmpty {
                        tintLayer(ids: primaryLit, scale: scale)
                        tintLayer(ids: secondaryLit, scale: scale)
                            .opacity(0.55)
                    }
                    ForEach(muscleSpecs.filter { $0.side == side }, id: \.id) { spec in
                        muscleOverlay(spec, scale: scale)
                    }
                }
                .frame(width: w, height: h)
                .position(x: proxy.size.width / 2, y: proxy.size.height / 2)
                // Tap handling (2026-11-10): a SINGLE tap-location
                // handler on the figure, NOT one Button per muscle.
                // Per-muscle Buttons never received taps on screen
                // (verified: shoulder x2 + abs x1 on build #4 marked
                // nothing, while the highlight renders in the right
                // place and the Front/Back picker in the same view
                // works). The container converts the tap to canvas
                // coordinates and hit-tests the muscle polygons in
                // code, topmost first. Gated on onTap so display-only
                // figures (workout, Body screen) get no gesture at all.
                .contentShape(Rectangle())
                .onTapGesture { location in
                    // The tap location arrives in the GEOMETRYREADER's
                    // (proxy) coordinate space, NOT the figure's local
                    // space — verified from the console on build #7:
                    // a dead-centre abs tap reported location
                    // (458.7, 136.3) in a 919x360 proxy, i.e. the
                    // figure's centre, while the figure itself is only
                    // 180x360. Dividing by scale alone gave canvas
                    // (509.6, 151.5) — off the 200x400 canvas entirely —
                    // so every tap reported "no polygon hit". Subtract
                    // the figure's origin in proxy space first: the
                    // figure is centred, so origin = (proxy - size)/2.
                    let origin = CGPoint(x: (proxy.size.width - w) / 2,
                                         y: (proxy.size.height - h) / 2)
                    let canvas = CGPoint(x: (location.x - origin.x) / scale,
                                         y: (location.y - origin.y) / scale)
                    guard let onTap else { return }
                    for spec in muscleSpecs.filter({ $0.side == side }).reversed() {
                        if overlayPath(spec, scale: 1.0).contains(canvas) {
                            onTap(spec.id)
                            return
                        }
                    }
                }
            }
            .frame(width: proxy.size.width, height: proxy.size.height)
        }
    }

    private func muscleOverlay(_ spec: MuscleSpec, scale: CGFloat) -> some View {
        let mainLit = highlighted.contains(spec.id)
        let injuredLit = !mainLit && injured.contains(spec.id)
        let state = mainLit || injuredLit ? nil : recovery[spec.id]
        let lit = mainLit || injuredLit || state != nil
        let secondary = mainLit && (primary.map { !$0.contains(spec.id) } ?? false)
        let litBase = state == .fresh ? Self.freshColor
            : state == .recovering ? Self.recoveringColor
            : injuredLit ? Self.litGlow : (litColor ?? Self.litGlow)
        // Colour comes from the tinted painting (tintLayer); no flat fill.
        // Resting: the detailed grey anatomy painting shows through.
        let fill: Color? = nil
        let shape = overlayPath(spec, scale: scale)
        // The overlay is a PLAIN view, not a Button: touch goes to
        // the figure's single tap-location handler (see BodyFigureView
        // body). Per-muscle Buttons never received taps on screen.
        // VoiceOver still gets a per-muscle button via the
        // accessibilityAction below, which is independent of touch
        // hit-testing.
        return ZStack {
            // Each shape view carries the FULL-canvas frame: a bare
            // Path sizes to its own bounding rect, and the ZStack
            // would center that rect on the canvas center (see the
            // note on the Button above). With the full frame the Path
            // draws at its true canvas coordinates.
            ZStack {
                shape
                    .fill(fill ?? Color.clear)
                    .frame(width: 200 * scale, height: 400 * scale)
                if lit {
                    // Hairline edge on every lit shape, in a darker shade of
                    // the highlight colour (Nov 12): the highlight colour
                    // with black laid over it, so it follows any accent.
                    ZStack {
                        shape.stroke(litBase, lineWidth: 0.8)
                        shape.stroke(Color.black.opacity(0.4), lineWidth: 0.8)
                    }
                    .opacity(secondary ? 0.6 : 1)
                    .frame(width: 200 * scale, height: 400 * scale)
                }
            }
            // Flat fills, no glow or pop: in the segmented style the
            // gaps between muscles already separate lit shapes, and the
            // approved preview has none.
            .animation(AppAnimation.snappy, value: lit)
        }
        .accessibilityLabel(spec.id.accessibilityLabel)
        .accessibilityValue(freshnessValue(for: spec))
        .accessibilityAddTraits(mainLit || injuredLit ? [.isButton, .isSelected] : .isButton)
        .accessibilityAction { onTap?(spec.id) }
    }

    /// VoiceOver freshness state for one muscle. Empty when the figure
    /// carries no recovery data (injury diagram, live workout), so
    /// nothing misleading is announced there.
    private func freshnessValue(for spec: MuscleSpec) -> String {
        switch recovery[spec.id] {
        case .fresh: return "Fresh"
        case .recovering: return "Recovering"
        case .none: return ""
        }
    }

    /// The shape for one body area: all of its exact outlines as one
    /// path (a muscle can be several painted pieces, e.g. two triceps
    /// heads).
    private func overlayPath(_ spec: MuscleSpec, scale: CGFloat) -> Path {
        // Smooth closed curve through the outline: a quadratic B-spline
        // whose control points are the outline vertices and whose knots
        // are the edge midpoints. No corners, no stair-steps (Nov 12:
        // straight segments looked rough when zoomed).
        var path = Path()
        for outline in spec.polygons where outline.count >= 3 {
            let pts = outline.map { CGPoint(x: $0.x * scale, y: $0.y * scale) }
            func mid(_ a: CGPoint, _ b: CGPoint) -> CGPoint { CGPoint(x: (a.x + b.x) / 2, y: (a.y + b.y) / 2) }
            path.move(to: mid(pts[pts.count - 1], pts[0]))
            for i in 0..<pts.count {
                path.addQuadCurve(to: mid(pts[i], pts[(i + 1) % pts.count]), control: pts[i])
            }
            path.closeSubpath()
        }
        return path
    }
}

