// MARK: - Injury diagram (setup quiz + Profile)

/// The tappable body for listing injuries. Front/back toggle, tap a
/// muscle to mark its body part (tap again to unmark) — the muscle
/// LIGHTS UP bright and stays lit until tapped again. Marked parts are
/// listed underneath as chips (full names, never cut off); no labels sit
/// on the figure itself.
struct BodyDiagramView: View {
    /// The injury zones the program works from.
    @Binding var selected: Set<BodyPart>
    /// The exact muscles tapped. Each tap marks and lights just that
    /// muscle, named on its chip (a tap used to light the whole zone and
    /// name the zone: biceps read "Left elbow").
    @Binding var muscles: Set<MuscleID>
    @State private var side: BodyDiagramSide = .front

    /// Zones marked before muscles were saved: none of their muscles is
    /// in `muscles`, so they show as the whole zone.
    private var zoneOnlyParts: Set<BodyPart> {
        selected.subtracting(Set(muscles.compactMap(\.bodyPart)))
    }

    /// Lit = the tapped muscles, plus every muscle of a zone-only part.
    private var litMuscles: Set<MuscleID> {
        let zones = zoneOnlyParts
        return Set(muscleSpecs.filter { spec in
            spec.side == side && (muscles.contains(spec.id)
                || spec.id.bodyPart.map { zones.contains($0) } == true)
        }.map { $0.id })
    }

    private func toggle(_ muscle: MuscleID) {
        var zones = zoneOnlyParts
        if muscles.contains(muscle) {
            muscles.remove(muscle)
        } else if let part = muscle.bodyPart, zones.contains(part) {
            // Part of a zone marked the old way: unmark the zone.
            zones.remove(part)
        } else {
            muscles.insert(muscle)
        }
        selected = zones.union(muscles.compactMap(\.bodyPart))
    }

    private func unmark(zone part: BodyPart) {
        var zones = zoneOnlyParts
        zones.remove(part)
        selected = zones.union(muscles.compactMap(\.bodyPart))
    }

    var body: some View {
        VStack(spacing: 12) {
            Picker("View", selection: $side) {
                ForEach(BodyDiagramSide.allCases, id: \.self) { side in
                    Text(side.label).tag(side)
                }
            }
            .pickerStyle(.segmented)
            .frame(maxWidth: 260)

            BodyFigureView(side: side, highlighted: litMuscles, onTap: { muscle in
                guard muscle.bodyPart != nil else { return }
                withAnimation(AppAnimation.snappy) { toggle(muscle) }
            }, onSideChange: { side = $0 })
            .frame(height: 360)
            .animation(AppAnimation.snappy, value: side)

            if !selected.isEmpty {
                markedChips
            } else {
                Text("Tap a muscle to mark it — tap again to unmark.")
                    .font(.caption)
                    .foregroundStyle(Theme.secondaryText)
            }
        }
    }

    private enum Chip: Hashable {
        case muscle(MuscleID)
        case zone(BodyPart)
        var label: String {
            switch self {
            case .muscle(let m): return m.accessibilityLabel
            case .zone(let p): return p.label
            }
        }
    }

    /// Marked spots as chips, two per row, full names, tap the × to unmark.
    private var markedChips: some View {
        let chips = (muscles.map(Chip.muscle) + zoneOnlyParts.map(Chip.zone))
            .sorted { $0.label < $1.label }
        return FlexibleChips(chips) { chip in
            HStack(spacing: 6) {
                Text(chip.label)
                Button {
                    withAnimation(AppAnimation.snappy) {
                        switch chip {
                        case .muscle(let m): toggle(m)
                        case .zone(let p): unmark(zone: p)
                        }
                    }
                } label: {
                    Image(systemName: "xmark.circle.fill")
                        .font(.caption)
                }
                .buttonStyle(.plain)
                .accessibilityLabel("Unmark \(chip.label)")
            }
            .font(.subheadline.weight(.semibold))
            .foregroundStyle(.white)
            .padding(.horizontal, 12)
            .padding(.vertical, 8)
            .background(Color.red.opacity(0.85))
            .clipShape(Capsule())
        }
    }
}

/// Wraps chips into rows (two per row, flexible).
private struct FlexibleChips<Item: Hashable, Content: View>: View {
    let items: [Item]
    let content: (Item) -> Content

    init(_ items: [Item], @ViewBuilder content: @escaping (Item) -> Content) {
        self.items = items
        self.content = content
    }

    var body: some View {
        // Two columns, wrapping rows.
        let rows = stride(from: 0, to: items.count, by: 2).map { i in
            Array(items[i..<min(i + 2, items.count)])
        }
        return VStack(alignment: .leading, spacing: 8) {
            ForEach(rows, id: \.self) { row in
                HStack(spacing: 8) {
                    ForEach(row, id: \.self) { item in
                        content(item)
                    }
                }
            }
        }
    }
}

// MARK: - Live workout body (real-time, on the workout screen)

/// The real-time body on the workout screen: it lights up the muscle
/// groups of the CURRENT exercise and flips front/back to show them.
/// `exerciseID` is the current exercise's library id; `nextExerciseID`
/// is the next exercise's. The muscles lit are the exercise's
/// `trainedMuscles` from `ExerciseLibrary` — the single source of truth
/// shared with exercise detail, program, recovery, and stretches —
/// never a diagram-local table. `muscle` / `nextMuscle` are fallbacks
/// for callers that only know a muscle group (primary only). Display
/// only — not tappable.
/// `figureHeight`: the figure's height. Nil = fill the available height
/// (propped/open layout, where the body should be BIG); a number = a
/// fixed height (compact layout, and the regular detail pane, which
/// scrolls).
struct LiveBodyView: View {
    // `var`, not `let`: a `let` with a default value is left OUT of the
    // synthesized memberwise initializer, so call sites could not pass
    // `exerciseID:` / `nextExerciseID:` at all (Xcode 27.2 build failure
    // 2026-11-10: "Extra arguments at positions #1, #2 in call"). These
    // are still inputs only — the view never writes them.
    var exerciseID: String? = nil
    var nextExerciseID: String? = nil
    var muscle: MuscleGroup? = nil
    var nextMuscle: MuscleGroup? = nil
    var figureHeight: CGFloat? = 300
    /// Optional hoisted side/flip (TodayView passes its own — Debug Pass
    /// 2, fold glitch): LiveBodyView is rebuilt per Today layout, so
    /// @State here alone would snap the figure back to the auto side on
    /// every fold. When the bindings are supplied, Today owns the values
    /// and this view restores them on appear and writes changes back;
    /// when nil (standalone uses) the local @State owns them as before.
    var sideBinding: Binding<BodyDiagramSide>? = nil
    var userFlippedBinding: Binding<Bool>? = nil
    @EnvironmentObject var store: WorkoutStore
    /// Starts on the last side shown (Today keeps it), not always Front.
    @State private var side: BodyDiagramSide = .front
    @State private var userFlipped = false
    /// Set once the side is settled on appear; until then nothing animates.
    @State private var settled = false
    /// What the figure lights up (DaRon): the working muscles by default,
    /// or injuries, recovery, or all three together. Kept across launches.
    @AppStorage("liveBodyHighlight") private var mode: LiveBodyHighlight = .working

    /// Injured areas marked in the profile (Injuries and All views).
    private var injuredMuscles: Set<MuscleID> {
        guard mode == .injuries || mode == .all else { return [] }
        return store.profile?.injuredMuscles ?? []
    }

    /// Fresh / recovering per muscle, from logged history (Recovery and
    /// All views) — the same map the Body page draws.
    private var recoveryMap: [MuscleID: MuscleRecovery] {
        guard mode == .recovery || mode == .all else { return [:] }
        let dates = store.lastTrainedDates()
        var map: [MuscleID: MuscleRecovery] = [:]
        for id in MuscleID.allCases {
            guard let group = id.muscleGroup else { continue }
            map[id] = store.recoveryState(for: group, dates: dates)
        }
        return map
    }

    /// The working muscles, when this view shows them.
    private var shownLit: Set<MuscleID> {
        mode == .working || mode == .all ? litMuscles : []
    }

    /// The button beside Front/Back that picks what's lit.
    private var highlightMenu: some View {
        Menu {
            Picker("Highlight", selection: $mode) {
                ForEach(LiveBodyHighlight.allCases, id: \.self) { m in
                    Label(m.label, systemImage: m.systemImage).tag(m)
                }
            }
        } label: {
            Image(systemName: mode.systemImage)
                .scaledFont(size: 15, weight: .semibold, maxScale: 1.3)
                .foregroundStyle(mode == .working ? Theme.text : accent)
                .frame(width: 36, height: 36)
                .liquidGlass(Circle())
                .contentShape(Circle())
        }
        .buttonStyle(.plain)
        .accessibilityLabel("Highlight")
        .accessibilityValue(mode.label)
    }

    /// What the caption says for the views other than Working.
    @ViewBuilder private var modeCaption: some View {
        switch mode {
        case .working:
            EmptyView()
        case .injuries:
            Text(injuredMuscles.isEmpty ? "No injuries marked" : "Injuries")
        case .recovery:
            (Text("Fresh").foregroundColor(BodyFigureView.freshColor) + Text(" · ")
                + Text("Recovering").foregroundColor(BodyFigureView.recoveringColor))
        case .all:
            (Text("Working").foregroundColor(accent) + Text(" · ")
                + Text("Injuries").foregroundColor(Color(red: 1.0, green: 0.45, blue: 0.1)) + Text(" · ")
                + Text("Fresh").foregroundColor(BodyFigureView.freshColor) + Text(" · ")
                + Text("Recovering").foregroundColor(BodyFigureView.recoveringColor))
        }
    }

    /// The exercise (library or custom) for the current id, if it resolves.
    private var resolvedExercise: LibraryExercise? {
        exerciseID.flatMap { ExerciseLibrary.byId($0, plus: store.customExercises) }
    }

    /// The next exercise, if it resolves.
    private var resolvedNextExercise: LibraryExercise? {
        nextExerciseID.flatMap { ExerciseLibrary.byId($0, plus: store.customExercises) }
    }

    /// The primary muscle of the current exercise (resolved, else fallback).
    private var primaryMuscle: MuscleGroup? {
        resolvedExercise?.muscle ?? muscle
    }

    /// The primary muscle of the next exercise (resolved, else fallback).
    private var nextPrimaryMuscle: MuscleGroup? {
        resolvedNextExercise?.muscle ?? nextMuscle
    }

    /// The muscle groups lit for the current exercise: its
    /// `trainedMuscles` (primary + secondaries) when it resolves, else
    /// the fallback primary alone.
    private var litGroups: [MuscleGroup] {
        resolvedExercise?.trainedMuscles ?? (muscle.map { [$0] } ?? [])
    }

    private var litMuscles: Set<MuscleID> {
        Set(muscleSpecs.filter { spec in
            spec.side == side && spec.id.muscleGroup.map { litGroups.contains($0) } == true
        }.map { $0.id })
    }

    /// The prime mover's regions: lit at full strength; the rest of
    /// `litMuscles` are synergists and draw lighter.
    private var primaryLitMuscles: Set<MuscleID> {
        guard let primaryMuscle else { return litMuscles }
        return litMuscles.filter { $0.muscleGroup == primaryMuscle }
    }

    /// The app's effective accent (same rule as the menu button and the
    /// Live Activity): Pro users' chosen accent, else the default.
    private var accent: Color {
        store.isPro ? store.settings.accentColor.color : Theme.accent
    }

    /// "Back · Biceps · Forearms" with the prime mover in bold, so the
    /// caption matches the figure's emphasis.
    private var litCaption: Text {
        litGroups.enumerated().reduce(Text("")) { text, item in
            let (index, group) = item
            let separator = index == 0 ? Text("") : Text(" · ")
            let label = group == primaryMuscle
                ? Text(group.label).bold().foregroundColor(.primary)
                : Text(group.label)
            return text + separator + label
        }
    }

    /// The side that shows the primary muscle first: a row shows the
    /// back, a squat shows the front (quads), a pushdown shows the back
    /// (triceps). Counting synergist groups hid the prime mover — a row
    /// used to open on the front (biceps + forearms outnumber the back
    /// group 2-to-1) and a pushdown opened on the front too, where the
    /// triceps do not even appear. The primary muscle's side wins; the
    /// group count only breaks a tie when the primary straddles sides.
    private var bestSide: BodyDiagramSide {
        if let primaryMuscle {
            return primaryMuscle.isBackSide ? .back : .front
        }
        let backCount = litGroups.filter { $0.isBackSide }.count
        let frontCount = litGroups.count - backCount
        return backCount > frontCount ? .back : .front
    }

    private var sidePicker: some View {
        // Only the user's own pick counts as a flip: the auto side
        // (bestSide on appear / exercise change) also writes `side`, and
        // an onChange(of: side) here marked those as user flips, so the
        // figure stopped following the exercise after the first change.
        Picker("View", selection: Binding(
            get: { side },
            set: { newValue in
                userFlipped = true
                side = newValue
            }
        )) {
            ForEach(BodyDiagramSide.allCases, id: \.self) { side in
                Text(side.label).tag(side)
            }
        }
        .pickerStyle(.segmented)
    }

    var body: some View {
        VStack(spacing: 8) {
            // Front/Back always sits under the title (DaRon Nov 12), so it
            // never collides with the clock and Wi-Fi in the top corner.
            VStack(alignment: .leading, spacing: 6) {
                Text(mode.title)
                    .font(.headline)
                HStack(spacing: 8) {
                    sidePicker.frame(maxWidth: 160)
                    Spacer(minLength: 0)
                    highlightMenu
                }
            }
            .frame(maxWidth: .infinity, alignment: .leading)
            BodyFigureView(side: side, highlighted: shownLit,
                           recovery: recoveryMap,
                           litColor: accent, primary: primaryLitMuscles,
                           injured: injuredMuscles,
                           // Turning it by hand is a pick: it stops following the exercise.
                           onSideChange: { userFlipped = true; side = $0 })
                .modifier(LiveBodyFigureHeight(height: figureHeight))
                // No animation until the first side is settled, so the
                // figure never plays a flip as it appears.
                .animation(settled ? AppAnimation.snappy : nil, value: side)
                .animation(settled ? AppAnimation.snappy : nil, value: litMuscles)
                .animation(settled ? AppAnimation.snappy : nil, value: mode)
            if mode != .working {
                modeCaption
                    .font(.caption)
                    .foregroundStyle(Theme.secondaryText)
            }
            if !litGroups.isEmpty && (mode == .working || mode == .all) {
                litCaption
                    .font(.caption)
                    .foregroundStyle(Theme.secondaryText)
                    .multilineTextAlignment(.center)
            }
            if let nextPrimaryMuscle, nextPrimaryMuscle != primaryMuscle {
                Text("Next up: \(nextPrimaryMuscle.label)")
                    .font(.caption)
                    .foregroundStyle(Theme.secondaryText)
            }
        }
        .onAppear {
            // Opening the Duo builds this view afresh: it must appear
            // already on its side, still (DaRon: the body flickered as it
            // flipped from the default Front to Back, animated). So the
            // side is settled with animation off: the last side shown
            // (Today keeps it), a hand-picked flip, else the auto side.
            var still = Transaction()
            still.disablesAnimations = true
            withTransaction(still) {
                if userFlippedBinding?.wrappedValue == true, let sideBinding {
                    side = sideBinding.wrappedValue
                    userFlipped = true
                } else {
                    side = bestSide
                }
            }
        }
        .task { settled = true }
        .onChange(of: exerciseID) { _, _ in
            if !userFlipped {
                withAnimation(AppAnimation.snappy) { side = bestSide }
            }
        }
        .onChange(of: muscle) { _, _ in
            if !userFlipped {
                withAnimation(AppAnimation.snappy) { side = bestSide }
            }
        }
        // Write-through: a side/flip change here updates the hoisted
        // state, so the next layout instance restores it instead of
        // re-deriving it. (No loop: writing the binding re-renders with
        // the same values, which fires no further change.)
        .onChange(of: side) { _, newValue in
            sideBinding?.wrappedValue = newValue
        }
        .onChange(of: userFlipped) { _, newValue in
            userFlippedBinding?.wrappedValue = newValue
        }
    }
}

/// What the live body lights up.
enum LiveBodyHighlight: String, CaseIterable {
    case working, injuries, recovery, all
    var label: String {
        switch self {
        case .working: return "Working"
        case .injuries: return "Injuries"
        case .recovery: return "Recovery"
        case .all: return "All"
        }
    }
    var title: String {
        switch self {
        case .working: return "Working now"
        case .injuries: return "Injuries"
        case .recovery: return "Recovery"
        case .all: return "Everything"
        }
    }
    var systemImage: String {
        switch self {
        case .working: return "figure.strengthtraining.traditional"
        case .injuries: return "bandage"
        case .recovery: return "arrow.clockwise.heart"
        case .all: return "square.stack.3d.up"
        }
    }
}

/// The live body's figure height: a fixed height, or fill the available
/// height (when `height` is nil, e.g. the propped/open layout where the
/// body should be BIG and use the full pane).
private struct LiveBodyFigureHeight: ViewModifier {
    let height: CGFloat?
    func body(content: Content) -> some View {
        if let height {
            content.frame(height: height)
        } else {
            content.frame(maxWidth: .infinity, maxHeight: .infinity)
        }
    }
}

// MARK: - Body screen (recovery state, Fitbod pattern)

/// The Body screen (History → Body): the real figure, coloured by
/// recovery state from the user's own logged history — fresh muscles
/// (not trained within the muscle's recovery window: ~72 h large,
/// ~48 h small) bright pink, recently trained muscles purple, the
/// rest the image's own red. Stats at the top,
/// a rotate button to flip front/back, and tapping a muscle shows which
/// one it is (and lights it up).
struct BodyView: View {
    @Environment(\.fabBottomOffset) private var fabBottomOffset
    @EnvironmentObject var store: WorkoutStore
    @Environment(\.horizontalSizeClass) private var horizontalSizeClass
    @State private var side: BodyDiagramSide = .front
    @State private var tappedMuscle: MuscleID?

    /// Recovery colour per muscle, from the store's logged history.
    /// The dates are computed once, not per muscle.
    private var recovery: [MuscleID: MuscleRecovery] {
        let dates = store.lastTrainedDates()
        var map: [MuscleID: MuscleRecovery] = [:]
        for spec in muscleSpecs {
            guard let group = spec.id.muscleGroup else { continue }
            map[spec.id] = store.recoveryState(for: group, dates: dates)
        }
        return map
    }

    private var highlighted: Set<MuscleID> {
        tappedMuscle.map { [$0] } ?? []
    }

    var body: some View {
        ScrollView {
            VStack(spacing: 16) {
                statsRow
                legendRow
                BodyFigureView(side: side, highlighted: highlighted, recovery: recovery, onTap: { muscle in
                    withAnimation(AppAnimation.snappy) {
                        tappedMuscle = (tappedMuscle == muscle) ? nil : muscle
                    }
                }, onSideChange: { side = $0 })
                // D15 (2026-11-10): 360pt capped the figure at 180 wide
                // in the wide open-pose pane. Regular width gets 520pt
                // (figure 260 wide, +44%) while still fitting with the
                // stats/legend/Rotate button; compact stays 360pt.
                .frame(height: horizontalSizeClass == .regular ? 520 : 360)
                .animation(AppAnimation.snappy, value: side)
                if let tappedMuscle {
                    Text(tappedMuscle.accessibilityLabel)
                        .font(.headline)
                    if let group = tappedMuscle.muscleGroup {
                        Text(store.recoveryCaption(for: group))
                            .font(.subheadline)
                            .foregroundStyle(Theme.secondaryText)
                            .multilineTextAlignment(.center)
                    }
                }
                rotateButton
            }
            // Same 16pt sides/top as before; the bottom is the shared
            // LayoutClearance rule (Debug Pass 2) so the Rotate button
            // scrolls clear of the floating menu button — and of the
            // rest-timer panel while a rest runs. The old uniform 16pt
            // padding left it under the button at scroll-bottom.
            .padding(.horizontal, 16)
            .padding(.top, 16)
            .padding(.bottom, LayoutClearance.bottom(restActive: store.isRestActive, fabOffset: fabBottomOffset))
        }
        .navigationTitle("Body")
        .navigationBarTitleDisplayMode(.inline)
    }

    private var statsRow: some View {
        // Both cards the same height, tops level (the longer label wrapped
        // and made one card taller than the other).
        HStack(alignment: .top, spacing: 16) {
            statCard(value: store.daysSinceLastWorkout.map { "\($0)" } ?? "—",
                     label: "DAYS SINCE YOUR LAST WORKOUT")
            statCard(value: "\(store.freshMuscleGroups.count)",
                     label: "FRESH MUSCLE GROUPS")
        }
        .fixedSize(horizontal: false, vertical: true)
    }

    private func statCard(value: String, label: String) -> some View {
        VStack(spacing: 4) {
            Text(value)
                .scaledFont(size: 34, weight: .bold)
            Text(label)
                .font(.caption2.weight(.semibold))
                .foregroundStyle(Theme.secondaryText)
                .multilineTextAlignment(.center)
        }
        .frame(maxWidth: .infinity, maxHeight: .infinity, alignment: .top)
        .padding(.vertical, 12)
        .themeCard()
    }

    private var legendRow: some View {
        HStack(spacing: 16) {
            legendDot(color: BodyFigureView.freshColor, label: "Fresh")
            legendDot(color: BodyFigureView.recoveringColor, label: "Recovering")
            // Resting = not tracked for recovery, drawn in the plain grey
            // (the swatch was red, a colour nothing on the figure uses).
            legendDot(color: BodyFigureView.muscleRest, label: "Resting")
        }
        .font(.caption)
        .foregroundStyle(Theme.secondaryText)
    }

    private func legendDot(color: Color, label: String) -> some View {
        HStack(spacing: 6) {
            Circle().fill(color).frame(width: 10, height: 10)
                .shadow(color: color.opacity(0.5), radius: 4)
            Text(label)
        }
    }

    private var rotateButton: some View {
        Button {
            withAnimation(AppAnimation.snappy) {
                side = side == .front ? .back : .front
            }
        } label: {
            Label("Rotate — \(side == .front ? "Back" : "Front")", systemImage: "arrow.triangle.2.circlepath")
                .font(.subheadline.weight(.semibold))
        }
        .buttonStyle(.bordered)
    }
}

// MARK: - 3D body (Nov 14)

import SceneKit
import MetalKit

/// One muscle's colour on the 3D body. Strength 0…1 blends it over the grey.
struct BodyTint: Equatable {
    var color: Color
    var strength: Float
}

/// The MetaHuman body for the app, loaded once and shared by every figure.
/// Made by design/body-source/figure (export_model.py + make_assets.py):
///   BodyModel  raw mesh (positions, normals, uvs, triangle indices)
///   BodyColor  the grey anatomy, BodyShade its light/dark
///   BodyIDs    which area each texel belongs to (bodyModelAreas)
final class BodyModel {
    static let shared = BodyModel()

    let device: MTLDevice?
    private(set) var geometry: SCNGeometry?
    private(set) var colorTexture: MTLTexture?
    private(set) var shadeTexture: MTLTexture?
    private(set) var idTexture: MTLTexture?
    private var ids: [UInt8] = []
    private var idSize = (w: 0, h: 0)
    var isReady: Bool { geometry != nil && idTexture != nil && colorTexture != nil }

    /// Area index (texel value) → muscle, in ids.json order.
    static let areas: [MuscleID?] = [nil, .abs, .adductorLeft, .adductorRight, .ankleLeft, .ankleRight, .bicepsLeft, .bicepsRight, .calfLeft, .calfRight, .deltLeft, .deltRight, .elbowLeft, .elbowRight, .footLeft, .footRight, .forearmLeft, .forearmRight, .gluteLeft, .gluteRight, .groin, .hamstringLeft, .hamstringRight, .handLeft, .handRight, .head, .hipFlexorLeft, .hipFlexorRight, .kneeLeft, .kneeRight, .latLeft, .latRight, .lowerBack, .midBack, .neck, .obliqueLeft, .obliqueRight, .outerHipLeft, .outerHipRight, .pecLeft, .pecRight, .quadLeft, .quadRight, .rotatorCuffLeft, .rotatorCuffRight, .serratusLeft, .serratusRight, .shinLeft, .shinRight, .trapLeft, .trapRight, .tricepsLeft, .tricepsRight, .wristLeft, .wristRight]
    static let index: [MuscleID: Int] = {
        var m: [MuscleID: Int] = [:]
        for (i, a) in areas.enumerated() { if let a { m[a] = i } }
        return m
    }()

    private init() {
        device = MTLCreateSystemDefaultDevice()
        guard let device else { return }
        geometry = Self.loadGeometry()
        let loader = MTKTextureLoader(device: device)
        func texture(_ name: String, srgb: Bool) -> MTLTexture? {
            guard let data = NSDataAsset(name: name)?.data else { return nil }
            return try? loader.newTexture(data: data, options: [
                .SRGB: srgb, .generateMipmaps: true,
                .textureStorageMode: MTLStorageMode.private.rawValue])
        }
        colorTexture = texture("BodyColor", srgb: true)
        shadeTexture = texture("BodyShade", srgb: false)
        loadIDs(device: device)
    }

    private static func loadGeometry() -> SCNGeometry? {
        guard let data = NSDataAsset(name: "BodyModel")?.data, data.count > 12 else { return nil }
        let nv = Int(data.withUnsafeBytes { $0.load(fromByteOffset: 4, as: UInt32.self) })
        let ni = Int(data.withUnsafeBytes { $0.load(fromByteOffset: 8, as: UInt32.self) })
        let pos = 12, nrm = pos + nv * 12, uv = nrm + nv * 12, idx = uv + nv * 8
        guard data.count >= idx + ni * 4 else { return nil }
        let sources = [
            SCNGeometrySource(data: data.subdata(in: pos..<nrm), semantic: .vertex, vectorCount: nv,
                              usesFloatComponents: true, componentsPerVector: 3, bytesPerComponent: 4, dataOffset: 0, dataStride: 12),
            SCNGeometrySource(data: data.subdata(in: nrm..<uv), semantic: .normal, vectorCount: nv,
                              usesFloatComponents: true, componentsPerVector: 3, bytesPerComponent: 4, dataOffset: 0, dataStride: 12),
            SCNGeometrySource(data: data.subdata(in: uv..<idx), semantic: .texcoord, vectorCount: nv,
                              usesFloatComponents: true, componentsPerVector: 2, bytesPerComponent: 4, dataOffset: 0, dataStride: 8),
        ]
        let element = SCNGeometryElement(data: data.subdata(in: idx..<(idx + ni * 4)), primitiveType: .triangles,
                                         primitiveCount: ni / 3, bytesPerIndex: 4)
        return SCNGeometry(sources: sources, elements: [element])
    }

    private func loadIDs(device: MTLDevice) {
        guard let data = NSDataAsset(name: "BodyIDs")?.data, data.count > 8 else { return }
        let w = Int(data.withUnsafeBytes { $0.load(fromByteOffset: 0, as: UInt32.self) })
        let h = Int(data.withUnsafeBytes { $0.load(fromByteOffset: 4, as: UInt32.self) })
        guard let raw = try? (data.subdata(in: 8..<data.count) as NSData).decompressed(using: .zlib),
              raw.count == w * h else { return }
        ids = [UInt8](raw as Data); idSize = (w, h)
        let desc = MTLTextureDescriptor.texture2DDescriptor(pixelFormat: .r8Unorm, width: w, height: h, mipmapped: false)
        desc.usage = .shaderRead
        guard let tex = device.makeTexture(descriptor: desc) else { return }
        ids.withUnsafeBytes { tex.replace(region: MTLRegionMake2D(0, 0, w, h), mipmapLevel: 0, withBytes: $0.baseAddress!, bytesPerRow: w) }
        idTexture = tex
    }

    /// The muscle at a texture coordinate (from a hit test).
    func area(at uv: CGPoint) -> MuscleID? {
        guard idSize.w > 0 else { return nil }
        let x = min(max(Int(uv.x * CGFloat(idSize.w)), 0), idSize.w - 1)
        let y = min(max(Int(uv.y * CGFloat(idSize.h)), 0), idSize.h - 1)
        let i = Int(ids[y * idSize.w + x])
        return i < Self.areas.count ? Self.areas[i] : nil
    }

    /// Lit muscles drawn in the shader: the area's palette colour, shaded by
    /// the painting's own light and dark, plus a little glow (bloom).
    static let shader = """
    #pragma arguments
    texture2d<float> bodyIDs;
    texture2d<float> bodyShade;
    texture2d<float> bodyPalette;
    #pragma body
    // The four area texels around this point, each looked up in the
    // palette and blended like a linear filter: smooth edges on every lit
    // muscle instead of texel steps (a plain nearest lookup was jagged).
    constexpr sampler gatherS(filter::nearest, address::clamp_to_edge);
    constexpr sampler linearS(filter::linear, mip_filter::linear, address::clamp_to_edge);
    float2 uv = _surface.diffuseTexcoord;
    float2 size = float2(bodyIDs.get_width(), bodyIDs.get_height());
    float2 f = fract(uv * size - 0.5);
    float4 ids = bodyIDs.gather(gatherS, uv) * 255.0;
    float4 w = float4((1.0 - f.x) * f.y, f.x * f.y, f.x * (1.0 - f.y), (1.0 - f.x) * (1.0 - f.y));
    float3 rgb = float3(0.0);
    float a = 0.0;
    for (int k = 0; k < 4; k++) {
        uint area = min(uint(round(ids[k])), 63u);
        float4 t = bodyPalette.read(uint2(area, 0u));
        rgb += t.rgb * t.a * w[k];
        a += t.a * w[k];
    }
    if (a > 0.002) {
        float3 tint = rgb / a;
        float shade = bodyShade.sample(linearS, uv).r;
        // Squared shade: the fibres and the lines between muscles stay
        // visible instead of one flat block of colour.
        float3 lit = tint * (0.08 + 1.05 * shade * shade);
        _surface.diffuse.rgb = mix(_surface.diffuse.rgb, lit, a);
        // The accent's glow: bright enough for the camera's bloom.
        _surface.emission.rgb += lit * 0.4 * a;
    }
    """
}

/// The 3D body in a SceneKit view: drag sideways to turn it, tap a muscle.
struct Body3DView: UIViewRepresentable {
    let side: BodyDiagramSide
    let palette: [MuscleID: BodyTint]
    var onTap: ((MuscleID) -> Void)?
    var onSideChange: ((BodyDiagramSide) -> Void)?

    func makeUIView(context: Context) -> BodySceneView { BodySceneView(side: side) }

    func updateUIView(_ view: BodySceneView, context: Context) {
        view.onTap = onTap
        view.onSideChange = onSideChange
        view.setPalette(palette)
        view.show(side)
    }
}

final class BodySceneView: SCNView, UIGestureRecognizerDelegate {
    var onTap: ((MuscleID) -> Void)?
    var onSideChange: ((BodyDiagramSide) -> Void)?
    private let model = BodyModel.shared
    private let turntable = SCNNode()
    private let cameraNode = SCNNode()
    private var material: SCNMaterial?
    private var paletteTexture: MTLTexture?
    private var lastPalette: [MuscleID: BodyTint]? = nil
    private var yaw: Float = 0
    private var shownSide: BodyDiagramSide = .front

    /// Starts already facing `side`: no turn plays as the figure appears.
    init(side: BodyDiagramSide) {
        shownSide = side
        yaw = side == .front ? 0 : .pi
        super.init(frame: .zero, options: [SCNView.Option.preferredDevice.rawValue: model.device as Any,
                                           SCNView.Option.preferLowPowerDevice.rawValue: true])
        backgroundColor = .clear
        isOpaque = false
        antialiasingMode = .multisampling4X
        // Draws only when something changes (a turn, a new highlight).
        rendersContinuously = false
        isPlaying = false
        let scene = SCNScene()
        scene.background.contents = UIColor.clear
        self.scene = scene

        if let geometry = model.geometry?.copy() as? SCNGeometry {
            let m = SCNMaterial()
            m.lightingModel = .lambert
            m.diffuse.contents = model.colorTexture
            m.diffuse.mipFilter = .linear
            m.shaderModifiers = [.surface: BodyModel.shader]
            m.setValue(SCNMaterialProperty(contents: model.idTexture as Any), forKey: "bodyIDs")
            m.setValue(SCNMaterialProperty(contents: model.shadeTexture as Any), forKey: "bodyShade")
            geometry.materials = [m]
            material = m
            turntable.addChildNode(SCNNode(geometry: geometry))
        }
        turntable.eulerAngles.y = yaw
        scene.rootNode.addChildNode(turntable)

        let cam = SCNCamera()
        cam.fieldOfView = 18
        cam.zNear = 0.5; cam.zFar = 40
        cam.wantsHDR = true
        cam.wantsExposureAdaptation = false
        cam.bloomIntensity = 1.1
        cam.bloomThreshold = 0.75
        cam.bloomBlurRadius = 10
        cameraNode.camera = cam
        scene.rootNode.addChildNode(cameraNode)
        pointOfView = cameraNode

        // Lights stay with the viewer: whichever side faces you is lit.
        func light(_ type: SCNLight.LightType, _ intensity: CGFloat, _ euler: SCNVector3) {
            let l = SCNLight(); l.type = type; l.intensity = intensity
            let n = SCNNode(); n.light = l; n.eulerAngles = euler
            scene.rootNode.addChildNode(n)
        }
        light(.ambient, 380, SCNVector3Zero)
        light(.directional, 900, SCNVector3(-0.35, 0.45, 0))      // key, above right
        light(.directional, 650, SCNVector3(0.1, .pi + 0.5, 0))  // rim from behind: the outline holds on black

        let pan = UIPanGestureRecognizer(target: self, action: #selector(panned(_:)))
        pan.delegate = self
        addGestureRecognizer(pan)
        addGestureRecognizer(UITapGestureRecognizer(target: self, action: #selector(tapped(_:))))
    }

    required init?(coder: NSCoder) { fatalError("init(coder:) has not been implemented") }

    /// Whole body in view, arms included, at any width.
    override func layoutSubviews() {
        super.layoutSubviews()
        guard bounds.width > 0, bounds.height > 0 else { return }
        let aspect = Float(bounds.width / bounds.height)
        let halfHeight = max(1.06, 0.68 / aspect)
        let distance = halfHeight / tan(Float(9) * .pi / 180)
        cameraNode.position = SCNVector3(0, 0, distance)
    }

    func setPalette(_ palette: [MuscleID: BodyTint]) {
        guard palette != lastPalette, let device = model.device, let material else { return }
        lastPalette = palette
        var bytes = [UInt8](repeating: 0, count: 64 * 4)
        for (id, tint) in palette {
            guard let i = BodyModel.index[id], i < 64 else { continue }
            var r: CGFloat = 0, g: CGFloat = 0, b: CGFloat = 0, a: CGFloat = 0
            UIColor(tint.color).getRed(&r, green: &g, blue: &b, alpha: &a)
            // sRGB → linear: the shader works in linear light.
            func lin(_ c: CGFloat) -> UInt8 { UInt8(max(0, min(255, pow(Double(c), 2.2) * 255))) }
            bytes[i * 4] = lin(r); bytes[i * 4 + 1] = lin(g); bytes[i * 4 + 2] = lin(b)
            bytes[i * 4 + 3] = UInt8(max(0, min(255, tint.strength * Float(a) * 255)))
        }
        let desc = MTLTextureDescriptor.texture2DDescriptor(pixelFormat: .rgba8Unorm, width: 64, height: 1, mipmapped: false)
        guard let tex = device.makeTexture(descriptor: desc) else { return }
        bytes.withUnsafeBytes { tex.replace(region: MTLRegionMake2D(0, 0, 64, 1), mipmapLevel: 0, withBytes: $0.baseAddress!, bytesPerRow: 64 * 4) }
        paletteTexture = tex
        // A new property (not new bytes in the old one) so SceneKit redraws.
        material.setValue(SCNMaterialProperty(contents: tex), forKey: "bodyPalette")
    }

    /// Turn to face the given side, the short way round, unless a drag
    /// already has it there.
    func show(_ side: BodyDiagramSide) {
        guard side != shownSide else { return }
        shownSide = side
        let target: Float = side == .front ? 0 : .pi
        var delta = (target - yaw).truncatingRemainder(dividingBy: 2 * .pi)
        if delta > .pi { delta -= 2 * .pi } else if delta < -.pi { delta += 2 * .pi }
        turn(to: yaw + delta, duration: 0.55)
    }

    private func turn(to angle: Float, duration: CFTimeInterval) {
        yaw = angle
        SCNTransaction.begin()
        SCNTransaction.animationDuration = duration
        SCNTransaction.animationTimingFunction = CAMediaTimingFunction(name: .easeOut)
        turntable.eulerAngles.y = angle
        SCNTransaction.commit()
    }

    /// The side facing the viewer at the current turn.
    private var facing: BodyDiagramSide { cos(yaw) >= 0 ? .front : .back }

    @objc private func panned(_ g: UIPanGestureRecognizer) {
        let dx = Float(g.translation(in: self).x)
        g.setTranslation(.zero, in: self)
        switch g.state {
        case .changed:
            yaw += dx * 0.012
            SCNTransaction.begin(); SCNTransaction.disableActions = true
            turntable.eulerAngles.y = yaw
            SCNTransaction.commit()
        case .ended, .cancelled:
            // A flick keeps turning a little and eases out.
            let v = Float(g.velocity(in: self).x) * 0.012
            turn(to: yaw + v * 0.18, duration: 0.6)
        default: break
        }
        if facing != shownSide {
            shownSide = facing
            onSideChange?(facing)
        }
    }

    @objc private func tapped(_ g: UITapGestureRecognizer) {
        guard let onTap else { return }
        let hits = hitTest(g.location(in: self), options: [.searchMode: SCNHitTestSearchMode.closest.rawValue])
        guard let hit = hits.first, let area = model.area(at: hit.textureCoordinates(withMappingChannel: 0)) else { return }
        onTap(area)
    }

    /// Only sideways drags turn the body; up and down still scroll the page.
    override func gestureRecognizerShouldBegin(_ g: UIGestureRecognizer) -> Bool {
        guard let pan = g as? UIPanGestureRecognizer else { return true }
        let v = pan.velocity(in: self)
        return abs(v.x) > abs(v.y)
    }
}
